import { Component, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { HttpClientModule } from '@angular/common/http';
// Ajusta la ruta de importación según donde hayas puesto el servicio finalmente
import { DashboardService, DashboardData } from '../services/dashboard.service'; 

@Component({
  selector: 'app-dashboard',
  standalone: true,
  imports: [CommonModule, HttpClientModule],
  templateUrl: './dashboard.component.html',
  styleUrls: ['./dashboard.component.scss']
})
export class DashboardComponent implements OnInit {
  // Datos para la vista
  menuCounts = { examenes: 0, tareas: 0, reuniones: 0 };
  notifications: any[] = [];
  
  // Calendario
  currentDate = new Date(2026, 0, 1); // Enero 2026
  daysInMonth: any[] = [];
  weekDays = ['Dom', 'Lun', 'Mar', 'Mié', 'Jue', 'Vie', 'Sáb'];
  
  // Mapa para buscar eventos rápidamente por fecha
  eventsMap: { [key: string]: string } = {}; 

  constructor(private dashboardService: DashboardService) {}

  ngOnInit() {
    this.loadDashboardData();
  }

  loadDashboardData() {
    this.dashboardService.getData().subscribe({
      next: (data: DashboardData) => {
        this.menuCounts = data.menuCounts;
        this.notifications = data.notifications;
        
        // Mapeamos eventos: "2026-01-09" -> "examen"
        data.calendarEvents.forEach(evt => {
          // Aseguramos formato YYYY-MM-DD recortando la hora si viene
          const dateStr = new Date(evt.date).toISOString().split('T')[0];
          this.eventsMap[dateStr] = evt.type;
        });

        this.generateCalendar();
      },
      error: (err) => console.error('Error conectando al backend:', err)
    });
  }

  generateCalendar() {
    const year = this.currentDate.getFullYear();
    const month = this.currentDate.getMonth();
    
    // 1. Obtener día de la semana del 1ro del mes (0=Dom, 1=Lun...)
    const firstDayIndex = new Date(year, month, 1).getDay();
    // 2. Total de días en el mes
    const totalDays = new Date(year, month + 1, 0).getDate();
    
    const days = [];

    // Rellenar huecos vacíos antes del día 1
    for (let i = 0; i < firstDayIndex; i++) {
      days.push({ day: null, class: 'empty' });
    }

    // Rellenar los días reales
    for (let i = 1; i <= totalDays; i++) {
      // Construir string fecha local YYYY-MM-DD
      // Nota: Mes es base 0, por eso +1
      const dayString = `${year}-${(month + 1).toString().padStart(2, '0')}-${i.toString().padStart(2, '0')}`;
      
      const eventType = this.eventsMap[dayString]; // ¿Hay evento hoy?

      days.push({ 
        day: i, 
        type: eventType, // 'examen', 'tarea', etc.
        class: 'active' 
      });
    }

    this.daysInMonth = days;
  }

  // Helper para clases CSS de notificaciones
  getNotifClass(type: string): string {
    const classes: any = { 
      'examen': 'notif-red', 
      'tarea': 'notif-green', 
      'reunion': 'notif-purple' 
    };
    return classes[type] || '';
  }
}
